import java.util.Arrays;

public class IncreasingRunFinderTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            check("longestRun({1,3,2,4,6,8,1})", "[2, 4]",
                    Arrays.toString(IncreasingRunFinder.longestRun(new int[] {1, 3, 2, 4, 6, 8, 1})));
            check("longestRun({}) is {-1, 0}", "[-1, 0]",
                    Arrays.toString(IncreasingRunFinder.longestRun(new int[] {})));
            check("longestRun({7})", "[0, 1]",
                    Arrays.toString(IncreasingRunFinder.longestRun(new int[] {7})));
            check("longestRun({5,4,3,2}) all descending", "[0, 1]",
                    Arrays.toString(IncreasingRunFinder.longestRun(new int[] {5, 4, 3, 2})));
            check("longestRun({2,2,2}) equal is not increasing", "[0, 1]",
                    Arrays.toString(IncreasingRunFinder.longestRun(new int[] {2, 2, 2})));
            check("longestRun({1,2,0,3,0}) earliest wins tie", "[0, 2]",
                    Arrays.toString(IncreasingRunFinder.longestRun(new int[] {1, 2, 0, 3, 0})));
            check("longestRun({-9,-4,-4,-1,0})", "[2, 3]",
                    Arrays.toString(IncreasingRunFinder.longestRun(new int[] {-9, -4, -4, -1, 0})));
            check("longestRun({1,2,3,4}) whole array", "[0, 4]",
                    Arrays.toString(IncreasingRunFinder.longestRun(new int[] {1, 2, 3, 4})));
        } catch (Throwable t) {
            System.out.println("FAIL  unexpected exception: " + t);
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

